import json, math, numpy as np
from scipy.optimize import milp, LinearConstraint, Bounds
from scipy.sparse import lil_matrix

with open('data.json') as f: data=json.load(f)
V=data['vehicle_count']; cap=data['vehicle_capacity']; pw=data['penalty_weight']
stations=data['stations']; n=len(stations); M=n
ids=[s['id'] for s in stations]
R=3960.0
def dist_coord(a,b):
    lat1,lon1=map(math.radians,a); lat2,lon2=map(math.radians,b)
    val=math.sin(lat1)*math.sin(lat2)+math.cos(lat1)*math.cos(lat2)*math.cos(lon1-lon2)
    return R*math.acos(max(-1,min(1,val)))
coords=[(data['depot']['latitude'],data['depot']['longitude'])]+[(s['latitude'],s['longitude']) for s in stations]
N=n+1 # node 0 depot
D=np.zeros((N,N))
for i in range(N):
 for j in range(N):
  if i"'!=j: D[i,j]=dist_coord(coords[i],coords[j])

idx={}; lb=[]; ub=[]; c=[]; integ=[]
def add(name, lo, hi, obj=0, integer=False):
    k=len(lb); idx[name]=k; lb.append(lo); ub.append(hi); c.append(obj); integ.append(1 if integer else 0); return k
# y[v,p,node], p 0..M+1
for v in range(V):
 for p in range(M+2):
  for node in range(N): add(('"'y',v,p,node),0,1,0,True)
# w[v,p,i,j] transition p->p+1 for p 0..M
for v in range(V):
 for p in range(M+1):
  for i in range(N):
   for j in range(N): add(('w',v,p,i,j),0,1,D[i,j],True)
# pickups/dropoffs at intermediate positions and station nodes 1..n
for v in range(V):
 for p in range(1,M+1):
  for node in range(1,N):
   add(('pick',v,p,node),0,cap,0,True)
   add(('drop',v,p,node),0,cap,0,True)
# loads
for v in range(V):
 add(('start_load',v),0,cap,0,True)
 for p in range(1,M+1): add(('load',v,p),0,cap,0,True)
 add(('end_load',v),0,cap,0,True)
# station dev variables
for node in range(1,N): add(('dev',node),0,1000,pw,False)

rows=[]; lows=[]; highs=[]
def cons(terms, lo, hi):
    rows.append(terms); lows.append(lo); highs.append(hi)
# one node per pos
for v in range(V):
 for p in range(M+2):
  cons([(idx[('y',v,p,node)],1) for node in range(N)],1,1)
 # depot fixed at endpoints; no depot-start only station at pos? endpoint fixed by y00=1 and others zero via one-node + constraints
 cons([(idx[('y',v,0,0)],1)],1,1)
 cons([(idx[('y',v,M+1,0)],1)],1,1)
 for p in range(1,M+1):
  # once depot padding starts, it continues
  if p<M:
   cons([(idx[('y',v,p,0)],1),(idx[('y',v,p+1,0)],-1)],-np.inf,0)
 # vehicle must visit some stations
 cons([(idx[('y',v,p,node)],1) for p in range(1,M+1) for node in range(1,N)],1,np.inf)
 # vehicle visits each station no more than once
 for node in range(1,N):
  cons([(idx[('y',v,p,node)],1) for p in range(1,M+1)],0,1)
# linearize transitions w and force selected pair
for v in range(V):
 for p in range(M+1):
  cons([(idx[('w',v,p,i,j)],1) for i in range(N) for j in range(N)],1,1)
  for i in range(N):
   cons([(idx[('w',v,p,i,j)],1) for j in range(N)] + [(idx[('y',v,p,i)],-1)],0,0)
  for j in range(N):
   cons([(idx[('w',v,p,i,j)],1) for i in range(N)] + [(idx[('y',v,p+1,j)],-1)],0,0)
# no self station->same station transition (already no repeat, but okay no issue); service link and sign restrictions
for v in range(V):
 for p in range(1,M+1):
  for node,s in enumerate(stations, start=1):
   y=idx[('y',v,p,node)]; pk=idx[('pick',v,p,node)]; dr=idx[('drop',v,p,node)]
   cons([(pk,1),(y,-cap)],-np.inf,0)
   cons([(dr,1),(y,-cap)],-np.inf,0)
   t=s['net_rebalancing_target']
   if t>=0:
    cons([(dr,1)],0,0)
   else:
    cons([(pk,1)],0,0)
# load transitions
for v in range(V):
 for p in range(1,M+1):
  terms=[]
  if p==1: terms.append((idx[('start_load',v)],-1))
  else: terms.append((idx[('load',v,p-1)],-1))
  terms.append((idx[('load',v,p)],1))
  for node in range(1,N):
   terms.append((idx[('pick',v,p,node)],-1))
   terms.append((idx[('drop',v,p,node)],1))
  cons(terms,0,0)
 cons([(idx[('end_load',v)],1),(idx[('load',v,M)],-1)],0,0)
# station inventory, target deviation
for node,s in enumerate(stations, start=1):
 net_terms=[]
 pick_terms=[]; drop_terms=[]
 for v in range(V):
  for p in range(1,M+1):
   pick_terms.append((idx[('pick',v,p,node)],1)); drop_terms.append((idx[('drop',v,p,node)],1))
   net_terms.append((idx[('pick',v,p,node)],1)); net_terms.append((idx[('drop',v,p,node)],-1))
 # inventory: initial - picked + dropped in [0, capacity] => net pickup <= initial; net pickup >= initial-capacity
 cons(net_terms, s['initial_bikes']-s['station_capacity'], s['initial_bikes'])
 # dev >= net-target and target-net
 dev=idx[('dev',node)]; target=s['net_rebalancing_target']
 cons(net_terms+[(dev,-1)], -np.inf, target)
 cons(net_terms+[(dev,1)], target, np.inf)
 # optional no overserve beyond target direction to tighten
 if target>=0:
  cons(net_terms,0,target)
 else:
  cons(net_terms,target,0)

m=len(rows); nv=len(lb)
A=lil_matrix((m,nv))
for r,terms in enumerate(rows):
 for k,val in terms: A[r,k]+=val
print('vars',nv,'constraints',m,'nnz',A.nnz)
res=milp(c=np.array(c), integrality=np.array(integ), bounds=Bounds(lb,ub), constraints=LinearConstraint(A.tocsr(), np.array(lows), np.array(highs)), options={'time_limit':300, 'mip_rel_gap':0})
print(res.success,res.message,'fun',res.fun,'mip_gap',getattr(res,'mip_gap',None),'nodes',getattr(res,'mip_node_count',None))
if not res.success:
 print(res)
 raise SystemExit
x=res.x
# extract report
vehicles=[]
station_tot={s['id']:{'pick':0,'drop':0} for s in stations}
travel=0
for v in range(V):
 route=['depot_start']; stops=[]
 start=round(x[idx[('start_load',v)]])
 for p in range(1,M+1):
  node=max(range(N), key=lambda nd:x[idx[('y',v,p,nd)]])
  if node==0: continue
  sid=ids[node-1]
  pk=sum(x[idx[('pick',v,p,node)]] for _ in [0])
  dr=sum(x[idx[('drop',v,p,node)]] for _ in [0])
  pk=round(pk); dr=round(dr); load=round(x[idx[('load',v,p)]])
  route.append(sid)
  stops.append({'station_id':sid,'bikes_picked_up':float(pk),'bikes_dropped_off':float(dr),'load_after_stop':float(load)})
  station_tot[sid]['pick']+=pk; station_tot[sid]['drop']+=dr
 route.append('depot_end')
 end=round(x[idx[('end_load',v)]])
 # compute travel from route ids
 seq=[0]+[ids.index(r)+1 for r in route[1:-1]]+[0]
 tv=sum(D[seq[i],seq[i+1]] for i in range(len(seq)-1))
 travel+=tv
 vehicles.append({'vehicle_id':v+1,'start_load':float(start),'route':route,'stops':stops,'end_load':float(end)})
report_st=[]; total_unmet=0
for node,s in enumerate(stations,start=1):
 sid=s['id']; pick=station_tot[sid]['pick']; drop=station_tot[sid]['drop']; net=pick-drop; unmet=abs(s['net_rebalancing_target']-net); total_unmet+=unmet
 report_st.append({'station_id':sid,'net_rebalancing_target':float(s['net_rebalancing_target']),'total_bikes_picked_up':float(pick),'total_bikes_dropped_off':float(drop),'net_bike_change':float(net),'unmet_rebalancing_amount':float(unmet)})
pen=pw*total_unmet
report={'summary':{'objective':travel+pen,'travel_distance_miles':travel,'unmet_rebalancing_penalty':pen,'total_unmet_rebalancing_amount':float(total_unmet)},'vehicles':vehicles,'stations':report_st}
with open('report.json','w') as f: json.dump(report,f,indent=2)
print(json.dumps(report['summary'],indent=2))
for veh in vehicles: print(veh)
